CREATE TABLE members (id BIGSERIAL PRIMARY KEY, card_number VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(40), membership_type VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', expires_on DATE, unpaid_fines NUMERIC(10,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, parent_id BIGINT REFERENCES categories(id));
CREATE TABLE books (id BIGSERIAL PRIMARY KEY, title VARCHAR(300) NOT NULL, subtitle VARCHAR(300), authors TEXT NOT NULL, isbn VARCHAR(32) NOT NULL UNIQUE, publisher VARCHAR(200), publication_year INTEGER, edition VARCHAR(80), language VARCHAR(80), category_id BIGINT REFERENCES categories(id), description TEXT, tags TEXT, price NUMERIC(10,2) NOT NULL DEFAULT 0, cover_url TEXT, ebook_url TEXT, digital_license_limit INTEGER NOT NULL DEFAULT 0, borrow_count BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_books_category ON books(category_id); CREATE INDEX idx_books_title ON books(title);
CREATE TABLE copies (id BIGSERIAL PRIMARY KEY, book_id BIGINT NOT NULL REFERENCES books(id), barcode VARCHAR(80) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', shelf_location VARCHAR(120), acquired_on DATE, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_copies_book_status ON copies(book_id,status);
CREATE TABLE loans (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id), copy_id BIGINT NOT NULL REFERENCES copies(id), borrowed_at TIMESTAMPTZ NOT NULL, due_at TIMESTAMPTZ NOT NULL, returned_at TIMESTAMPTZ, renewal_count INTEGER NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE UNIQUE INDEX uq_active_loan_copy ON loans(copy_id) WHERE status='ACTIVE'; CREATE INDEX idx_loans_status_due ON loans(status,due_at); CREATE INDEX idx_loans_member ON loans(member_id);
CREATE TABLE reservations (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id), book_id BIGINT NOT NULL REFERENCES books(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), status VARCHAR(20) NOT NULL DEFAULT 'WAITING', ready_until TIMESTAMPTZ, copy_id BIGINT REFERENCES copies(id));
CREATE INDEX idx_reservations_book_status ON reservations(book_id,status,created_at);
CREATE TABLE fines (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id), loan_id BIGINT REFERENCES loans(id), amount NUMERIC(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'UNPAID', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), paid_at TIMESTAMPTZ, waived_by VARCHAR(180), reason TEXT);
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, actor VARCHAR(180), action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(100), before_value JSONB, after_value JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id), kind VARCHAR(80) NOT NULL, message TEXT NOT NULL, sent_at TIMESTAMPTZ, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE digital_access (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES members(id), book_id BIGINT NOT NULL REFERENCES books(id), opened_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, closed_at TIMESTAMPTZ);
